import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];
const NIVEAUX_STUDENT = ['Primaire', 'Collège', 'Lycée 1ère', 'Lycée 2ème', 'Lycée 3ème (Bac)', 'Université'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    niveau: '', tarifs_matieres: [], certificats: [], photo_url: null
  });
  const [structure, setStructure] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  const [showCertModal, setShowCertModal] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => { fetchProfileData(); }, [user]);

  const fetchProfileData = async () => {
    try {
      const isProf = user?.role === 'professeur';
      const route = isProf ? '/api/professeurs/me' : '/api/etudiants/me';
      const res = await api.get(route);
      setForm(prev => ({ ...prev, ...res.data, user_prenom: res.data.prenom || res.data.user_prenom, user_nom: res.data.nom || res.data.user_nom }));
      if (isProf) {
        const resStruct = await api.get('/api/admin/referentiel/structure');
        setStructure(resStruct.data);
      }
      setLoading(false);
    } catch (e) { console.error(e); setLoading(false); }
  };

  const handleInput = (key, val) => setForm({ ...form, [key]: val });

  // --- LOGIQUE TARIFS AVEC MODE ---
  const isSelected = (matId, nivId, mode) => 
    form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId && t.mode === mode);

  const getTarif = (matId, nivId, mode) => 
    form.tarifs_matieres?.find(t => t.matiere_id === matId && t.niveau_id === nivId && t.mode === mode)?.tarif || '';

  const handleToggleMatiere = (matId, nivId, mode) => {
    let list = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId, mode)) {
      list = list.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId && t.mode === mode));
    } else {
      list.push({ matiere_id: matId, niveau_id: nivId, mode: mode, tarif: 20 });
    }
    setForm({ ...form, tarifs_matieres: list });
  };

  const handlePriceChange = (matId, nivId, mode, price) => {
    const list = form.tarifs_matieres.map(t => 
      (t.matiere_id === matId && t.niveau_id === nivId && t.mode === mode) ? { ...t, tarif: parseFloat(price) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: list });
  };

  const handleSave = async () => {
    try {
      const isProf = user?.role === 'professeur';
      const route = isProf ? '/api/professeurs/me' : '/api/etudiants/me';
      await api.put(route, {
        nom: form.user_nom, prenom: form.user_prenom, ville: form.ville,
        telephone: form.telephone, bio: form.bio,
        ...(isProf ? { tarifs_complets: form.tarifs_matieres } : { niveau: form.niveau })
      });
      setSaved(true); setTimeout(() => setSaved(false), 3000);
      alert("✅ Profil enregistré !");
    } catch (e) { alert('Erreur sauvegarde'); }
  };

  // --- PHOTOS & CERTIFS ---
  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0]; if (!file) return;
    const fd = new FormData(); fd.append('file', file);
    try {
      const res = await api.post('/api/professeurs/me/photo', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      setForm({ ...form, photo_url: res.data.url });
    } catch (e) { alert("Erreur photo"); }
  };

  const handleCertUpload = async (e) => {
    e.preventDefault();
    const fd = new FormData(); fd.append('titre', newCert.titre); fd.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      setShowCertModal(false); fetchProfileData();
    } catch (e) { alert("Erreur certificat"); }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '12px', fontSize: '.9rem', width: '100%', outline: 'none', marginBottom: '15px' };

  if (loading) return <div style={{padding: 50, textAlign: 'center'}}>Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* HEADER */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 30, marginBottom: 32, background: 'var(--card)', padding: 24, borderRadius: 24, border: '1px solid var(--border)' }}>
        <div style={{ position: 'relative' }}>
          <div style={{ width: 100, height: 100, borderRadius: '50%', overflow: 'hidden', border: '3px solid var(--accent)', background: 'var(--surface2)' }}>
            <img src={form.photo_url ? `http://localhost:8001${form.photo_url}` : 'https://ui-avatars.com/api/?name=' + form.user_prenom} alt="Avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>
          {user?.role === 'professeur' && (
            <label style={{ position: 'absolute', bottom: 0, right: 0, background: 'var(--accent)', width: 30, height: 30, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', border: '2px solid var(--card)' }}>
              📷 <input type="file" hidden onChange={handlePhotoUpload} />
            </label>
          )}
        </div>
        <div>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.6rem' }}>{form.user_prenom} {form.user_nom}</h2>
          <p style={{ color: 'var(--text2)', textTransform: 'capitalize' }}>Compte {user?.role}</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '450px 1fr' : '1fr', gap: 30 }}>

        {/* COLONNE GAUCHE */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>👤 Mon Identité</h3>
            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Prénom</label>
            <input style={inp} value={form.user_prenom || ''} onChange={e => handleInput('user_prenom', e.target.value)} />
            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Nom</label>
            <input style={inp} value={form.user_nom || ''} onChange={e => handleInput('user_nom', e.target.value)} />
            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Email</label>
            <input style={{...inp, opacity: 0.6}} value={form.email || ''} readOnly />
            {user?.role === 'étudiant' && (
              <>
                <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Niveau</label>
                <select style={inp} value={form.niveau} onChange={e => handleInput('niveau', e.target.value)}>
                  {NIVEAUX_STUDENT.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </>
            )}
            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Téléphone</label>
            <input style={inp} value={form.telephone || ''} onChange={e => handleInput('telephone', e.target.value)} />
            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ville</label>
            <select style={inp} value={form.ville} onChange={e => handleInput('ville', e.target.value)}>
               {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
            <button onClick={handleSave} style={{ width:'100%', background:'var(--accent)', color:'#fff', border:'none', padding:14, borderRadius:12, fontWeight:600 }}>Enregistrer</button>
          </div>

          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3>📝 Ma Bio</h3>
              <textarea style={{ ...inp, height: 120, resize: 'none' }} value={form.bio || ''} onChange={e => handleInput('bio', e.target.value)} />
            </div>
          )}
        </div>

        {/* COLONNE DROITE : TARIFS PAR MODE */}
        {user?.role === 'professeur' && (
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>
            {structure.map(dom => (
              <div key={dom.id} style={{ marginBottom: 35 }}>
                <div style={{ color: 'var(--accent)', fontWeight: 800, fontSize: '1.1rem', marginBottom: 15, borderBottom: '2px solid var(--accent)', paddingBottom: 5 }}>📂 {dom.nom.toUpperCase()}</div>
                {dom.niveaux?.map(niv => (
                  <div key={niv.id} style={{ marginLeft: 15, marginBottom: 25, background: 'var(--surface2)', padding: 20, borderRadius: 20, border: '1px solid var(--border)' }}>
                    <div style={{ fontWeight: 700, fontSize: '1rem', marginBottom: 15 }}>🎓 {niv.nom}</div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: 15 }}>
                      {niv.matieres?.map(mat => (
                        <div key={mat.id} style={{ background: 'var(--card)', padding: '15px', borderRadius: 12, border: '1px solid var(--border)' }}>
                          <div style={{ fontWeight: 600, marginBottom: 10, color: 'var(--accent)' }}>{mat.nom}</div>

                          {/* SÉLECTION DES MODES */}
                          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                            {/* Mode En Ligne */}
                            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                              <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '.85rem', cursor: 'pointer' }}>
                                <input type="checkbox" checked={isSelected(mat.id, niv.id, 'en_ligne')} onChange={() => handleToggleMatiere(mat.id, niv.id, 'en_ligne')} />
                                🌐 En ligne
                              </label>
                              {isSelected(mat.id, niv.id, 'en_ligne') && (
                                <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                                  <input type="number" value={getTarif(mat.id, niv.id, 'en_ligne')} onChange={e => handlePriceChange(mat.id, niv.id, 'en_ligne', e.target.value)} style={{ width: 60, background: 'var(--bg)', color: '#fff', border: '1px solid var(--border)', textAlign: 'center', borderRadius: 5 }} />
                                  <span style={{ fontSize: '.7rem' }}>DT/H</span>
                                </div>
                              )}
                            </div>

                            {/* Mode Présentiel */}
                            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                              <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '.85rem', cursor: 'pointer' }}>
                                <input type="checkbox" checked={isSelected(mat.id, niv.id, 'presentiel')} onChange={() => handleToggleMatiere(mat.id, niv.id, 'presentiel')} />
                                🏠 Présentiel
                              </label>
                              {isSelected(mat.id, niv.id, 'presentiel') && (
                                <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                                  <input type="number" value={getTarif(mat.id, niv.id, 'presentiel')} onChange={e => handlePriceChange(mat.id, niv.id, 'presentiel', e.target.value)} style={{ width: 60, background: 'var(--bg)', color: '#fff', border: '1px solid var(--border)', textAlign: 'center', borderRadius: 5 }} />
                                  <span style={{ fontSize: '.7rem' }}>DT/H</span>
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            ))}
            <button onClick={handleSave} style={{ width: '100%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', color: '#fff', border: 'none', padding: 18, borderRadius: 15, fontWeight: 700, cursor:'pointer' }}>Enregistrer mon catalogue</button>
          </div>
        )}
      </div>
    </div>
  );
}
